def get_coverage(slug):
 status=COMMON|STATUS[slug]
 main=[dict(topic=t,status=status.get(i,'地域単独で対応する公表値・現行条件は今回未取得。県全体や他地域の値を代用しない。'),anchor='#evidence' if i<27 else '#policy') for i,t in enumerate(TOPICS)]
 fields=[]
 for i,(topic,label) in enumerate(FIELD_NAMES,1):
  text='同等の地域単独調査・運行条件は今回未取得。湯布院の値を移植しない。'
  if i in [27,28,30,40]:text=main[24 if i==28 else 27 if i==30 else 22]['status']
  if i==7:text=main[13]['status']
  if i in [9,10]:text=main[0]['status']+' 湯布院駅周辺調査と同じ標本ではない。'
  if i==36:text=main[23]['status']
  if i==6 and slug=='usuki':text='2025年秋・臼杵石仏で745回答。来訪者標本の条件を本文に明記。'
  if i in [18,19,20,21,42,43,44] and slug=='usuki':text=main[20]['status']
  if i in [23,24] and slug=='kunisaki':text='補助対象ツアーの人数・消費推算は掲載。湯布院と同条件の助成要件・調査票ではない。'
  if i>=46:text='湯布院2020年無料デマンド実験に対応する同条件実験は未確認。地域の現行交通・別制度の実績で代用しない。'
  fields.append(dict(yufuin_record=f'{i:02}',topic=topic,indicator=label,regional_status=text,anchor='#evidence'))
 return dict(checkedAt='2026-11-04',scope='調査項目の対応であり、測定条件の同等性や調査完了率ではない。',main_topics=main,field_records=fields)
